function agruparPorEstado(tareas) {
  return tareas.reduce((grupos, tarea) => {
    if (!grupos[tarea.estado]) grupos[tarea.estado] = [];
    grupos[tarea.estado].push(tarea);
    return grupos;
  }, {});
}

