function Carrito({ products = [] }) {
  function reducer(state, action) {
    if (action.type === "ADD") {
      return { cantidades: { ...state.cantidades, [action.id]: (state.cantidades[action.id] || 0) + 1 } };
    }
    return state;
  }
  const [state, dispatch] = React.useReducer(reducer, { cantidades: {} });
  const total = products.reduce((sum, product) => sum + product.price * (state.cantidades[product.id] || 0), 0);
  return (
    <section>
      {products.map(product => <button key={product.id} data-add={product.id} onClick={() => dispatch({ type: "ADD", id: product.id })}>Agregar {product.name}</button>)}
      <output className="total">{total}</output>
    </section>
  );
}

