    button.className = "incrementar";
    button.textContent = "Sumar";
    button.addEventListener("click", () => { this.valor += 1; this.render(); });
    this.shadowRoot.replaceChildren(output, button);
    this.render();
  }
  render() { this.shadowRoot.querySelector(".valor").textContent = String(this.valor); }
