class ProductoCard extends HTMLElement {
  static get observedAttributes() { return ["nombre", "precio"]; }
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
  }
  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.isConnected) this.render(); }
  render() {
    const nombre = this.getAttribute("nombre") || "Producto";
    const precio = this.getAttribute("precio") || "0";
    this.shadowRoot.innerHTML = `<article><h2 class="nombre"></h2><p>Precio: <strong class="precio"></strong></p></article>`;
    this.shadowRoot.querySelector(".nombre").textContent = nombre;
    this.shadowRoot.querySelector(".precio").textContent = precio;
  }
}
customElements.define("producto-card", ProductoCard);

