class ListaTareas extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this.tareas = [];
  }
  connectedCallback() {
    this.shadowRoot.innerHTML = `<form><input class="nueva-tarea" aria-label="Nueva tarea"><button class="agregar" type="submit">Agregar</button></form><ul class="lista"></ul>`;
    this.shadowRoot.querySelector("form").addEventListener("submit", event => {
      event.preventDefault();
      const input = this.shadowRoot.querySelector(".nueva-tarea");
      this.agregarTarea(input.value);
      input.value = "";
    });
  }
  agregarTarea(texto) {
    const limpio = String(texto).trim();
    if (!limpio) return;
    this.tareas.push(limpio);
    const item = document.createElement("li");
    item.className = "tarea";
    item.textContent = limpio;
    this.shadowRoot.querySelector(".lista").append(item);
    this.dispatchEvent(new CustomEvent("tarea-agregada", { detail: { texto: limpio }, bubbles: true, composed: true }));
  }
}
customElements.define("lista-tareas", ListaTareas);

