const CarritoVue = {
  props: { products: { type: Array, default: () => [] } },
  setup(props) {
    const cantidades = Vue.reactive({});
    const agregar = id => { cantidades[id] = (cantidades[id] || 0) + 1; };
    const total = Vue.computed(() => props.products.reduce((sum, product) => sum + product.price * (cantidades[product.id] || 0), 0));
    return { cantidades, agregar, total };
  },
  template: '<section><button v-for="product in products" :key="product.id" :data-add="product.id" @click="agregar(product.id)">Agregar {{ product.name }}</button><output class="total">{{ total }}</output></section>'
};

